            queue = deque()
            queue.append(u)
            visited = set()
            while queue:
                current = queue.popleft()
                if current in visited:
                    continue
                visited.add(current)
                # Recompute temp_E[current]
                k = len(edges[current])
                sum_e = sum(temp_E[j] for j in edges[current])
                new_val = 1.0 + sum_e / k
                if abs(new_val - temp_E[current]) > 1e-12:
                    temp_E[current] = new_val
                    for pred in rev_edges[current]:
                        if pred not in visited:
                            queue.append(pred)
            # Update min_E
            if temp_E[1] < min_E:
                min_E = temp_E[1]

    print("{0:.10f}".format(min_E))

