    # We'll use dynamic programming
    # E[v] = 1 + sum(E[u] for u in adj[v]) / len(adj[v])
    # Since the graph is a DAG, we can process nodes in reverse order
    E = [0.0] * (N+1)
    for v in range(N, 0, -1):
        if v == N:
            E[v] = 0.0
        else:
            k = len(adj[v])
            if k == 0:
                E[v] = float('inf')
            else:
                sum_e = sum(E[u] for u in adj[v])
                E[v] = 1.0 + sum_e / k

