    min_E = E[1]
    for i in range(M):
        s, t = edges[i]
        # Check if blocking this edge is allowed
        # Check if s has more than one outgoing edge
        if len(adj[s]) == 1:
            continue  # blocking this edge would leave s with no outgoing edges
        # Now, simulate blocking this edge
