from functools import lru_cache

MOD = 10**9 + 7

def main():
    n, k = map(int, sys.stdin.readline().split())

    @lru_cache(maxsize=None)
    def dp(pos, used, current_sum):
        if pos == n:
            return 1 if current_sum == k else 0
        res = 0
        for i in range(1, n+1):
            if not (used >> (i-1) & 1):
                new_used = used | (1 << (i-1))
                contribution = abs(pos + 1 - i)
                res += dp(pos + 1, new_used, (current_sum + contribution) % MOD)
                res %= MOD
        return res

    print(dp(0, 0, 0))

