from functools import lru_cache

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    K = int(data[1])
    A = list(map(int, data[2:2+N]))

    max_bit = 40  # since K can be up to 1e12, which is about 40 bits
    cnt_1 = [0] * (max_bit + 1)
    for a in A:
        for j in range(max_bit + 1):
            if (a >> j) & 1:
                cnt_1[j] += 1

    # Precompute the bits of K
    k_bits = [0] * (max_bit + 1)
    for j in range(max_bit + 1):
        k_bits[j] = (K >> j) & 1

    @lru_cache(maxsize=None)
    def dfs(bit, tight):
        if bit < 0:
            return 0
        max_sum = 0
        k_bit = k_bits[bit]
        if tight:
            if k_bit == 1:
                # choose 0 or 1
                # choose 0
                contribution_0 = (N - cnt_1[bit]) * (1 << bit)
                res_0 = contribution_0 + dfs(bit - 1, False)
                # choose 1
                contribution_1 = cnt_1[bit] * (1 << bit)
                res_1 = contribution_1 + dfs(bit - 1, True)
                max_sum = max(res_0, res_1)
            else:
                # k_bit is 0, can only choose 0
                contribution_0 = cnt_1[bit] * (1 << bit)
                res_0 = contribution_0 + dfs(bit - 1, False)
                max_sum = res_0
        else:
            # can choose 0 or 1
            contribution_0 = cnt_1[bit] * (1 << bit)
            res_0 = contribution_0 + dfs(bit - 1, False)
            contribution_1 = (N - cnt_1[bit]) * (1 << bit)
            res_1 = contribution_1 + dfs(bit - 1, False)
            max_sum = max(res_0, res_1)
        return max_sum

    result = dfs(max_bit, True)
    print(result)

