def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    K = int(input[1])
    A = list(map(int, input[2:2+N]))

    max_bit = 40  # since K can be up to 1e12, 40 bits is sufficient

    # Precompute cnt0 and cnt1 for each bit
    cnt0 = [0] * (max_bit + 1)
    cnt1 = [0] * (max_bit + 1)
    for a in A:
        for b in range(max_bit + 1):
            if (a >> b) & 1:
                cnt1[b] += 1
            else:
                cnt0[b] += 1

    @lru_cache(maxsize=None)
    def dp(bit, tight):
        if bit < 0:
            return 0
        if tight:
            k_bit = (K >> bit) & 1
            if k_bit == 1:
                # Option 0: set to 0, tight becomes False
                res0 = cnt1[bit] * (1 << bit) + dp(bit - 1, False)
                # Option 1: set to 1, tight remains True
                res1 = cnt0[bit] * (1 << bit) + dp(bit - 1, True)
                return max(res0, res1)
            else:
                # Only option is 0, tight remains True
                return cnt1[bit] * (1 << bit) + dp(bit - 1, True)
        else:
            # Can choose 0 or 1, tight remains False
            res0 = cnt1[bit] * (1 << bit) + dp(bit - 1, False)
            res1 = cnt0[bit] * (1 << bit) + dp(bit - 1, False)
            return max(res0, res1)

    result = dp(max_bit, True)
    print(result)

