def compute_sum(N):
    if N < 0:
        return 0
    bits = []
    if N == 0:
        bits = [0]
    else:
        while N > 0:
            bits.append(N & 1)
            N >>= 1
        bits = bits[::-1]  # MSB first
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dp(pos, tight, zeros):
        if pos == len(bits):
            return pow(2, zeros, MOD)
        res = 0
        max_bit = bits[pos] if tight else 1
        for bit in [0, 1]:
            if bit > max_bit:
                continue
            new_tight = tight and (bit == max_bit)
            new_zeros = zeros + (1 if bit == 0 else 0)
            res = (res + dp(pos + 1, new_tight, new_zeros)) % MOD
        return res
    return dp(0, True, 0)

def main():
    import sys
    L, R = map(int, sys.stdin.readline().split())
    total = (compute_sum(R) - compute_sum(L-1)) % MOD
    print(total)

