def main():
    N_str = sys.stdin.readline().strip()
    K = int(sys.stdin.readline())
    N = list(map(int, N_str))
    L = len(N)

    @lru_cache(maxsize=None)
    def dp(pos, count, tight, started):
        if pos == L:
            return 1 if (count == K and started) else 0
        limit = N[pos] if tight else 9
        total = 0
        for d in range(0, limit + 1):
            new_tight = tight and (d == limit)
            new_started = started or (d != 0)
            new_count = count
            if new_started:
                if d != 0:
                    new_count += 1
            else:
                pass  # count remains the same
            if new_count > K:
                continue
            total += dp(pos + 1, new_count, new_tight, new_started)
        return total

    result = dp(0, 0, True, False)
    print(result)

