            else:
                # Subtract the patty
                x -= 1
                # Now check the second level-1 burger
                if x <= t:
                    return patty_count[level - 1] + count_patties(level - 1, x)
                else:
                    # Subtract the second level-1 burger
                    x -= t
                    # Now check the last bun
                    if x == 1:
                        return patty_count[level - 1] + 1
