def main():
    import sys
    input = sys.stdin.read
    N, X = map(int, input().split())

    # Precompute layers and patties for each level up to N
    layers = [0] * (N + 1)
    patties = [0] * (N + 1)
    layers[0] = 1
    patties[0] = 1
    for l in range(1, N + 1):
        layers[l] = 2 * layers[l - 1] + 3
        patties[l] = 2 * patties[l - 1] + 1

    def count_patties(level, x):
        if level == 0:
            return 1 if x >= 1 else 0
        total_layers = layers[level]
        if x == 0:
            return 0
        if x == 1:
            return 0
        if x == total_layers:
            return patties[level]
        # Check how much of the first part (bun + level-1 burger) is included
        # First layer is bun (1)
        if x == 1:
            return 0
        # After the first bun, we have the level-1 burger
        # So subtract the first layer (bun)
        x -= 1
        # Now check if x is within the level-1 burger
        if x <= layers[level - 1]:
            return count_patties(level - 1, x)
        # Else, we have the entire level-1 burger, plus the patty
        # Subtract the layers of level-1 burger
        x -= layers[level - 1]
        # Now, add the patty (1)
        res = patties[level - 1] + 1
        # Now check if x is within the next level-1 burger
        if x <= layers[level - 1]:
            return res + count_patties(level - 1, x)
        # Else, we have the entire next level-1 burger and the top bun
        # Subtract the layers of level-1 burger
        x -= layers[level - 1]
        # Add the patties from the next level-1 burger
        res += patties[level - 1]
        # Now, add the top bun (if x is 1)
        if x == 1:
            return res
        # If x is more than 1, it's invalid since total layers is known
        return res

    print(count_patties(N, X))

