def main():
    import sys
    sys.setrecursionlimit(1 << 25)
    X, Y = map(int, sys.stdin.readline().split())

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(n):
        if n > Y:
            return 0
        max_len = 1
        next_n = 2 * n
        if next_n <= Y:
            max_len = max(max_len, 1 + dfs(next_n))
        return max_len

    max_length = 0
    for n in range(X, Y + 1):
        current = dfs(n)
        if current > max_length:
            max_length = current
    print(max_length)

