from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:n+1]))

    pos = defaultdict(list)
    for idx, num in enumerate(a):
        pos[num].append(idx)

    current_pos = -1
    current_target = 1

    while True:
        if current_target not in pos:
            break
        positions = pos[current_target]
        idx = bisect.bisect_right(positions, current_pos)
        if idx < len(positions):
            current_pos = positions[idx]
            current_target += 1
        else:
            break

    if current_target == 1:
        print(-1)
    else:
        print(n - (current_target - 1))

