def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    idx = 0
    H = int(data[idx])
    idx += 1
    W = int(data[idx])
    idx += 1

    c = []
    for _ in range(10):
        row = list(map(int, data[idx:idx+10]))
        c.append(row)
        idx += 10

    # Read the grid
    grid = []
    for _ in range(H):
        row = list(map(int, data[idx:idx+W]))
        grid.append(row)
        idx += W

    # Precompute the minimum cost from each digit to 1
    # Using Dijkstra's algorithm for each digit
    min_cost = [float('inf')] * 10
    for start in range(10):
        # Dijkstra's algorithm from start to 1
        dist = [float('inf')] * 10
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            cost, u = heapq.heappop(heap)
            if cost > dist[u]:
                continue
            for v in range(10):
                if u != v:
                    new_cost = cost + c[u][v]
                    if new_cost < dist[v]:
                        dist[v] = new_cost
                        heapq.heappush(heap, (new_cost, v))
        min_cost[start] = dist[1]

    # Calculate total MP
    total = 0
    for row in grid:
        for d in row:
            if d != -1:
                total += min_cost[d]

    print(total)

