    N = int(input[0])
    K = int(input[1])
    a = list(map(int, input[2:2+N]))
    S = sorted(a)
    pre_sum = [0] * (N + 1)
    for i in range(N):
        pre_sum[i+1] = pre_sum[i] + S[i]
    total_sum = pre_sum[N]
    count = 0
    for i in range(N):
        target = a[i]
        j = bisect.bisect_left(S, target)
        total_rest = total_sum - target
        if target + total_rest < K:
            count += 1
            continue
        low, high = 0, N - 1
        answer_m = N
        while low <= high:
            mid = (low + high) // 2
            if mid <= j:
                sum_m = pre_sum[mid]
            else:
                sum_m = pre_sum[mid + 1] - S[j]
            if target + sum_m >= K:
                answer_m = mid
                high = mid - 1
            else:
                low = mid + 1
        if answer_m <= j:
            sum_m = pre_sum[answer_m]
        else:
            sum_m = pre_sum[answer_m + 1] - S[j]
        if sum_m >= K:
            count += 1
    print(count)

