    idx = 1
    for _ in range(N):
        x = int(data[idx])
        y = int(data[idx+1])
        d = data[idx+2]
        points.append((x, y, d))
        idx += 3

    # Process x direction
    max_A_x = -float('inf')
    min_A_x = float('inf')
    max_B_x = -float('inf')
    min_B_x = float('inf')
    max_C_x = -float('inf')
    min_C_x = float('inf')

    # R: x increases
    # L: x decreases
    # U/D: x is fixed
    for x, y, d in points:
        if d == 'R':
            if x > max_A_x:
                max_A_x = x
            if x < min_A_x:
                min_A_x = x
        elif d == 'L':
            if x > max_B_x:
                max_B_x = x
            if x < min_B_x:
                min_B_x = x
        else:
            if x > max_C_x:
                max_C_x = x
            if x < min_C_x:
                min_C_x = x

    # Process y direction
    max_A_y = -float('inf')
    min_A_y = float('inf')
    max_B_y = -float('inf')
    min_B_y = float('inf')
    max_C_y = -float('inf')
    min_C_y = float('inf')

    # U: y increases
    # D: y decreases
    # R/L: y is fixed
    for x, y, d in points:
        if d == 'U':
            if y > max_A_y:
                max_A_y = y
            if y < min_A_y:
                min_A_y = y
        elif d == 'D':
            if y > max_B_y:
                max_B_y = y
            if y < min_B_y:
                min_B_y = y
        else:
            if y > max_C_y:
                max_C_y = y
            if y < min_C_y:
                min_C_y = y

    # Collect all critical times for x and y directions
    critical_times = set()

    # For x direction
    # max_x(t) critical times
    t1_x = (max_B_x - max_A_x) / 2
    if t1_x >= 0:
        critical_times.add(t1_x)
    t2_x = max_C_x - max_A_x
    if t2_x >= 0:
        critical_times.add(t2_x)
    t3_x = max_B_x - max_C_x
    if t3_x >= 0:
        critical_times.add(t3_x)

    # min_x(t) critical times
    t4_x = (min_B_x - min_A_x) / 2
    if t4_x >= 0:
        critical_times.add(t4_x)
    t5_x = min_C_x - min_A_x
    if t5_x >= 0:
        critical_times.add(t5_x)
    t6_x = min_B_x - min_C_x
    if t6_x >= 0:
        critical_times.add(t6_x)

    # For y direction
    # max_y(t) critical times
    t1_y = (max_B_y - max_A_y) / 2
    if t1_y >= 0:
        critical_times.add(t1_y)
    t2_y = max_C_y - max_A_y
    if t2_y >= 0:
        critical_times.add(t2_y)
    t3_y = max_B_y - max_C_y
    if t3_y >= 0:
        critical_times.add(t3_y)

    # min_y(t) critical times
    t4_y = (min_B_y - min_A_y) / 2
    if t4_y >= 0:
        critical_times.add(t4_y)
    t5_y = min_C_y - min_A_y
    if t5_y >= 0:
        critical_times.add(t5_y)
    t6_y = min_B_y - min_C_y
    if t6_y >= 0:
        critical_times.add(t6_y)

    # Also add t=0
    critical_times.add(0.0)

    # Evaluate the product at all critical times
    min_val = float('inf')

    for t in critical_times:
        # Compute x coordinates at time t
        max_x = -float('inf')
        min_x = float('inf')
        for x, y, d in points:
            if d == 'R':
                curr_x = x + t
            elif d == 'L':
                curr_x = x - t
            else:
                curr_x = x
            if curr_x > max_x:
                max_x = curr_x
            if curr_x < min_x:
                min_x = curr_x

        # Compute y coordinates at time t
        max_y = -float('inf')
        min_y = float('inf')
        for x, y, d in points:
            if d == 'U':
                curr_y = y + t
            elif d == 'D':
                curr_y = y - t
            else:
                curr_y = y
            if curr_y > max_y:
                max_y = curr_y
            if curr_y < min_y:
                min_y = curr_y

        current_val = (max_x - min_x) * (max_y - min_y)
        if current_val < min_val:
            min_val = current_val

    print("{0:.10f}".format(min_val))

