MOD = 10**9 + 7

def main():
    import sys
    N = int(sys.stdin.readline())
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, tight):
        if pos == -1:
            return 1
        res = 0
        bit_val = (N >> pos) & 1
        for choice in [0, 1, 2]:
            if choice == 0:
                contribution = 0
            elif choice == 1:
                contribution = 1 << pos
            else:
                contribution = 3 << pos
            if tight:
                # Calculate the prefix_val
                prefix_val = (N >> (pos + 1)) << (pos + 1)
                new_sum = prefix_val + contribution
                if new_sum > N:
                    continue
                new_tight = (new_sum == N)
            else:
                new_tight = False
            res += dp(pos - 1, new_tight)
        return res % MOD

    result = dp(59, True)
    print(result)

