    def is_possible(K):
        flips = 0
        for i in range(N):
            current = int(S[i]) ^ flips
            if current == 1:
                # Need to flip
                if i + K - 1 >= N:
                    return False
                flips ^= 1
                # Flip from i to i + K - 1
                # This affects the next positions
        return True

    while left <= right:
        mid = (left + right) // 2
        if is_possible(mid):
            answer = mid
            left = mid + 1
        else:
            right = mid - 1
    print(answer)

